import {softmax} from './math.js';
import {ctcCollapse,ppoObjective,gcnAggregate,receptiveField,attentionExample,ganLoss} from './domain-math.js';
const C={lime:'#c5f66a',cyan:'#6bd5d4',orange:'#f4b880',purple:'#b9a1e8',pink:'#eab2c7',grid:'#304332',muted:'#8aa18a'};
const f=n=>(Math.abs(n)<.0005?0:n).toFixed(3);
function text(g,s,x,y,c=C.muted,size=18){g.fillStyle=c;g.font=`${size}px "DM Sans","Noto Sans SC",sans-serif`;g.textAlign='center';g.fillText(s,x,y)}
function line(g,x,y,X,Y,c=C.grid,width=2){g.beginPath();g.moveTo(x,y);g.lineTo(X,Y);g.strokeStyle=c;g.lineWidth=width;g.stroke()}
function dot(g,x,y,r=6,c=C.lime){g.beginPath();g.arc(x,y,r,0,Math.PI*2);g.fillStyle=c;g.fill()}
function box(g,x,y,w,h,c=C.grid){g.fillStyle=c;g.fillRect(x,y,w,h)}
function bars(g,values,labels,col=C.cyan,max=1){values.forEach((v,i)=>{const x=50+i*400/values.length,w=400/values.length-25,h=v/max*120;box(g,x,190-h,w,h,col);text(g,labels[i],x+w/2,223,C.muted,16);text(g,f(v),x+w/2,180-h,col,17)})}
export function drawDomain(g,id,p,t,mini){
switch(id){
case 29:{const a=p.a??.1,L=p.depth??4,plain=a**L,residual=(1+a)**L;for(let i=0;i<4;i++){const x=40+i*120;box(g,x,95,65,44,'#304c37');text(g,'F(x)',x+32,123,C.cyan);if(i<3){line(g,x+65,117,x+119,117,C.cyan);line(g,x+32,68,x+152,68,C.lime)}line(g,x+32,68,x+32,94,C.lime);dot(g,x+((t*.3)%1)*60,117,4,C.lime)}text(g,`plain = ${f(plain)}`,140,205,C.muted);text(g,`residual = ${f(residual)}`,360,205,C.lime);return `x=1 · ${L} 层线性化比较 · aᴸ=${plain!==0&&Math.abs(plain)<.001?plain.toExponential(2):f(plain)} · (1+a)ᴸ=${f(residual)}`}
case 30:{const patch=Number(p.patch??2),n=(8/patch)**2,s=18;for(let r=0;r<8;r++)for(let c=0;c<8;c++){const i=Math.floor(r/patch)*(8/patch)+Math.floor(c/patch),on=i===Math.floor(t*1.2)%n;box(g,35+c*s,35+r*s,16,16,on?'#9fc95a':(r+c)%3===0?'#5c9298':'#2d5054')}text(g,'→',225,118,C.cyan,28);for(let i=0;i<n;i++)box(g,285+i%8*21,67+Math.floor(i/8)*50,13,32,i===Math.floor(t*1.2)%n?C.lime:C.purple);text(g,`${n} tokens`,360,196,C.purple);return `8×8 图像 · ${patch}×${patch} patch · N=${n} · N²=${n*n} 个 token 配对（不含 CLS）`}
case 31:{const q=p.query??2,causal=(p.causal??'开启')==='开启',weights=attentionExample(q,causal);for(let i=0;i<5;i++){const x=60+i*96,allowed=!causal||i<=q;line(g,60+q*96,45,x,150,allowed?C.cyan+'99':C.grid,allowed?1+weights[i]*7:1);box(g,x-24,150,48,40,allowed?'#354b46':'#242e28');text(g,String(i),x,177,allowed?C.cyan:C.muted);text(g,f(weights[i]),x,222,allowed?C.lime:C.muted,16)}dot(g,60+q*96,45,10,C.lime);return `查询位置 ${q} · ${causal?'因果':'双向'}注意力权重 [${weights.map(f).join(', ')}]`}
case 32:{const pos=p.position??2,words=['我','正在','学习','深度','学习'];words.forEach((w,i)=>{const x=55+i*97;box(g,x-30,97,64,50,i===pos?'#5a6340':'#304143');text(g,i===pos?'MASK':w,x+2,127,i===pos?C.lime:C.cyan,i===pos?15:18);if(i!==pos)line(g,x+2,87,55+pos*97,40,C.cyan+'77',1);if(i===pos){line(g,x+2,153,x+2,183,C.lime);text(g,`目标: ${w}`,x+2,212,C.lime,16)}});return `预测位置 ${pos} · 原始目标“${words[pos]}” · 只在此目标位置计算 MLM 损失；未运行语言预测`}
case 33:{const mu=p.mu??0,threshold=p.threshold??1,r=ganLoss(mu,threshold);line(g,40,190,460,190);r.real.forEach(x=>dot(g,50+(x+3)/7*400,75,7,C.cyan));r.fake.forEach(x=>dot(g,50+(x+3)/7*400,140,7,C.pink));const X=50+(threshold+3)/7*400;line(g,X,35,X,185,C.lime,2);text(g,'真实样本',85,43,C.cyan);text(g,'生成样本',85,112,C.pink);text(g,`D threshold ${f(threshold)}`,325,222,C.lime,17);return `一维固定样本 · 判别器损失 ${f(r.d)} · 非饱和生成器损失 ${f(r.g)}`}
case 34:{const a=p.alpha??.7,x0=[0,.2,.9,.7,.3,.1,.8,1],eps=x0.map((_,i)=>Math.sin(i*2+1)),xt=x0.map((x,i)=>Math.sqrt(a)*x+Math.sqrt(1-a)*eps[i]);[x0,xt].forEach((arr,j)=>{arr.forEach((v,i)=>{const shade=Math.round(Math.max(0,Math.min(1,(v+1)/2))*180+30);box(g,52+j*255+i%4*35,54+Math.floor(i/4)*38,31,32,`rgb(${shade},${shade},${shade})`)});text(g,j?'加噪后 xₜ':'原始 x₀',110+j*255,176,j?C.pink:C.cyan)});text(g,'→',250,103,C.lime,28);return `信号系数 √ᾱ=${f(Math.sqrt(a))} · 噪声系数 √(1−ᾱ)=${f(Math.sqrt(1-a))} · xₜ[0]=${f(xt[0])}`}
case 35:{const next=p.nextq??2,terminal=p.terminal==='是',target=.5+(terminal?0:.9*next);[[55,'在线 Q',C.cyan],[220,'目标 Q',C.purple],[385,'TD 目标',C.lime]].forEach(([x,s,c])=>{box(g,x-35,83,115,70,'#293d30');text(g,s,x+23,110,c,17);text(g,x===55?'1.200':x===220?f(next):f(target),x+23,138,c,19)});line(g,125,118,180,118,C.grid);line(g,305,118,349,118,C.purple);text(g,'stop gradient',275,65,C.purple,16);text(g,'replay → online Q',150,207,C.muted,17);return `r=0.5, γ=0.9 · 目标=${f(target)} · 在线 Q=1.2 · TD 误差=${f(target-1.2)}`}
case 36:{const ratio=p.ratio??1.2,adv=p.adv??1,eps=p.epsilon??.2,toX=r=>45+(r-.4)/1.2*405,toY=y=>125-y*50;line(g,45,125,450,125);for(const r of [1-eps,1+eps])line(g,toX(r),30,toX(r),215,C.grid);for(let i=1;i<=100;i++){const x=.4+i/100*1.2,prev=x-.012;line(g,toX(prev),toY(prev*adv),toX(x),toY(x*adv),C.muted,1);line(g,toX(prev),toY(ppoObjective(prev,adv,eps)),toX(x),toY(ppoObjective(x,adv,eps)),C.lime,3)}dot(g,toX(ratio),toY(ppoObjective(ratio,adv,eps)),7,C.pink);text(g,'概率比 r →',370,233,C.muted,15);return `rA=${f(ratio*adv)} · L_clip=${f(ppoObjective(ratio,adv,eps))} · 策略损失为 −L_clip`}
case 37:{const layers=p.layers??1,h=gcnAggregate(layers),xs=[65,190,315,440];for(let i=1;i<4;i++)line(g,xs[i-1],105,xs[i],105,C.cyan,2);xs.forEach((x,i)=>{dot(g,x,105,22,i===Math.floor(t)%4?C.lime:C.cyan);text(g,String(i),x,112,'#17251b',18);text(g,f(h[i]),x,168,C.lime,20)});text(g,`normalized aggregation × ${layers}`,250,222,C.muted,16);return `${layers} 次归一化传播 · h=[${h.map(f).join(', ')}] · W=I，无激活`}
case 38:{const sharp=p.sharp??1,h=[.2,1,-.7],scores=h.map(v=>{const x=.2+sharp*v;return x>=0?x:.2*x}),w=softmax(scores);for(let i=0;i<3;i++){const x=90+i*160;line(g,250,48,x,165,C.cyan,1+w[i]*10);dot(g,x,165,15,C.cyan);text(g,f(w[i]),x,131,C.lime,19);text(g,`h=${h[i]}`,x,214,C.muted,17)}dot(g,250,48,18,C.lime);return `邻域注意力 [${w.map(f).join(', ')}] · 加权特征 ${f(h.reduce((s,v,i)=>s+v*w[i],0))}`}
case 39:{const forget=p.forget??.8,input=p.input??.3,c=forget+input*.6,h=.8*Math.tanh(c);line(g,45,186,455,186);for(let i=0;i<12;i++){const v=forget**i;box(g,55+i*33,181-v*110,22,v*110,C.cyan)}text(g,'旧记忆的保留比例 fᵗ',245,35,C.muted,18);return `c_prev=1, 候选 g=0.6, o=0.8 · c=${f(c)} · h=${f(h)}`}
case 40:{const layers=p.layers??3,base=p.base??2,R=receptiveField(layers,base);let offsets=new Set([0]);for(let l=0;l<layers;l++)offsets=new Set([...offsets].flatMap(v=>[v,v+base**l,v+2*base**l]));for(let i=0;i<24;i++){const used=offsets.has(23-i);box(g,23+i*19,128,14,30,used?C.cyan:C.grid);if(used)line(g,30+i*19,118,460,49,C.cyan+'55',1)}dot(g,460,49,9,C.lime);text(g,'只能看当前及过去',250,211,C.lime,18);return `k=3 · 膨胀率 [${Array.from({length:layers},(_,i)=>base**i).join(', ')}] · 感受野 R=${R}（画布展示 24 步）`}
case 41:{const path=p.path??'A A _ B B _',tokens=path.split(' '),result=ctcCollapse(path);tokens.forEach((s,i)=>{box(g,28+i*78,45,60,49,s==='_'?'#31382c':'#314e4b');text(g,s,58+i*78,77,s==='_'?C.muted:C.cyan,23)});text(g,'合并连续重复 → 移除 blank',250,135,C.muted,18);text(g,result,250,203,C.lime,34);return `帧级路径 [${path}] → 折叠序列 ${result}；这里只做路径折叠，不计算所有路径概率之和`}
case 42:{const tau=p.temperature??.5,w=softmax([1,.3,-.2].map(x=>x/tau));bars(g,w,['正目标','负候选 1','负候选 2'],C.purple);return `固定相似度 [1, 0.3, −0.2] · 温度 ${f(tau)} · 正目标概率 ${f(w[0])} · 对比损失 ${f(-Math.log(w[0]))}`}
}return ''}
